script:
var COLS = [["orderNr","Order No"],["customerName","Customer"],["salesChannel","Channel"],["createdByName","Created By"],["orderStatus","Status"],["orderType","Type"],["deliveryAt","Delivery"],["createdAt","Created"]];
var LINE_COLS = [["productName","Product"],["grade","Grade"],["packing","Packing"],["stems","Stems"],["packages","Pkgs"],["stemPrice","Stem Price"],["lineValue","Value"],["farmName","Farm"],["allocationStatus","Status"]];
function fmt(k, v){ if (v == null) return ""; if (k === "deliveryAt" || k === "offerExpirationDate") return String(v).slice(0,10); if (k === "createdAt" || k === "updatedAt") return String(v).slice(0,16); return String(v); }
function iso(d){ return d.toISOString().slice(0,10); }

var root = document.getElementById("so-root") || document.body;
root.innerHTML = "";
var head = document.createElement("div"); head.className = "so-head";
var h = document.createElement("h2"); h.textContent = "Sales Orders"; head.appendChild(h);
var sub = document.createElement("div"); sub.className = "so-sub"; sub.textContent = "Live from the Marginpar Fabric lakehouse \u2014 click an order to see its items"; head.appendChild(sub);
root.appendChild(head);

var card = document.createElement("div"); card.className = "so-card so-filter";
function mkDate(label){
  var f = document.createElement("div"); f.className = "so-field";
  var l = document.createElement("label"); l.textContent = label;
  var inp = document.createElement("input"); inp.type = "date";
  f.appendChild(l); f.appendChild(inp); card.appendChild(f); return inp;
}
var fromInp = mkDate("From");
var toInp = mkDate("To");
var btn = document.createElement("button"); btn.className = "btn btn-primary"; btn.textContent = "Apply"; card.appendChild(btn);
root.appendChild(card);

var status = document.createElement("div"); status.className = "so-count"; root.appendChild(status);
var tcard = document.createElement("div"); tcard.className = "so-card so-tablecard"; tcard.style.display = "none";
var table = document.createElement("table"); table.className = "so-table";
var thead = document.createElement("thead"); var htr = document.createElement("tr"); thead.appendChild(htr); table.appendChild(thead);
var tbody = document.createElement("tbody"); table.appendChild(tbody); tcard.appendChild(table); root.appendChild(tcard);
var caretTh = document.createElement("th"); caretTh.style.width = "28px"; htr.appendChild(caretTh);
COLS.forEach(function(c){ var th = document.createElement("th"); th.textContent = c[1]; htr.appendChild(th); });

function cellFor(key, val){
  var td = document.createElement("td");
  if (key === "orderStatus" && val){
    var b = document.createElement("span");
    var cls = (val === "confirmed") ? "badge-confirmed" : (val === "approved") ? "badge-approved" : "badge-default";
    b.className = "badge-status " + cls; b.textContent = val; td.appendChild(b);
  } else if (key === "orderNr"){
    var s = document.createElement("span"); s.className = "so-ordernr"; s.textContent = fmt(key, val); td.appendChild(s);
  } else { td.textContent = fmt(key, val); }
  return td;
}

function renderLines(container, lines){
  container.textContent = "";
  if (!lines.length){ var m = document.createElement("div"); m.className = "so-muted"; m.textContent = "No line items."; container.appendChild(m); return; }
  var t = document.createElement("table"); t.className = "so-lines";
  var th = document.createElement("thead"); var r = document.createElement("tr");
  LINE_COLS.forEach(function(c){ var x = document.createElement("th"); x.textContent = c[1]; r.appendChild(x); });
  th.appendChild(r); t.appendChild(th);
  var tb = document.createElement("tbody");
  lines.forEach(function(ln){ var tr = document.createElement("tr"); LINE_COLS.forEach(function(c){ var td = document.createElement("td"); var v = ln[c[0]]; td.textContent = (v == null ? "" : String(v)); tr.appendChild(td); }); tb.appendChild(tr); });
  t.appendChild(tb); container.appendChild(t);
}

function addRow(row){
  var tr = document.createElement("tr"); tr.className = "so-orow";
  var ctd = document.createElement("td"); var caret = document.createElement("span"); caret.className = "so-caret"; caret.textContent = "\u203a"; ctd.appendChild(caret); tr.appendChild(ctd);
  COLS.forEach(function(c){ tr.appendChild(cellFor(c[0], row[c[0]])); });
  var drow = document.createElement("tr"); drow.style.display = "none";
  var dtd = document.createElement("td"); dtd.colSpan = COLS.length + 1; dtd.className = "so-detail-cell"; drow.appendChild(dtd);
  var loaded = false;
  tr.onclick = function(){
    var open = drow.style.display === "none";
    drow.style.display = open ? "" : "none";
    tr.classList.toggle("so-open", open);
    if (open && !loaded){
      loaded = true; dtd.textContent = "Loading items...";
      fetch("/api/method/marginpar_integration.fabric.get_order_lines?order_id=" + encodeURIComponent(row.orderID), {headers:{Accept:"application/json"}, credentials:"same-origin"})
        .then(function(r){ if(!r.ok) throw new Error("HTTP " + r.status); return r.json(); })
        .then(function(d){ renderLines(dtd, d.message || []); })
        .catch(function(e){ dtd.textContent = "Could not load items: " + e.message; loaded = false; });
    }
  };
  tbody.appendChild(tr); tbody.appendChild(drow);
}

function load(){
  var qs = ["limit=500"];
  if (fromInp.value) qs.push("from_date=" + fromInp.value);
  if (toInp.value) qs.push("to_date=" + toInp.value);
  status.textContent = "Loading..."; tcard.style.display = "none";
  fetch("/api/method/marginpar_integration.fabric.get_orders?" + qs.join("&"), {headers:{Accept:"application/json"}, credentials:"same-origin"})
   .then(function(r){ if(!r.ok) throw new Error("HTTP " + r.status); return r.json(); })
   .then(function(d){
      var rows = d.message || [];
      tbody.innerHTML = "";
      rows.forEach(addRow);
      status.textContent = rows.length + " order(s)" + (rows.length === 500 ? " \u2014 capped at 500, narrow the range" : "");
      tcard.style.display = "";
   })
   .catch(function(e){ status.textContent = "Could not load orders: " + e.message; });
}
btn.onclick = load;
toInp.value = iso(new Date());
fromInp.value = iso(new Date(Date.now() - 30 * 864e5));
load();

style:
#so-root { max-width: 1120px; margin: 0 auto; }
.so-head { margin: 4px 0 18px; }
.so-head h2 { font-weight: 700; margin: 0; letter-spacing: -0.01em; }
.so-head .so-sub { color: #6b7280; font-size: 13px; margin-top: 2px; }
.so-card { background: #fff; border: 1px solid #ebeef0; border-radius: 12px; padding: 16px 18px; margin-bottom: 18px; box-shadow: 0 1px 2px rgba(16,24,40,.04); }
.so-filter { display: flex; align-items: flex-end; gap: 14px; flex-wrap: wrap; }
.so-filter .so-field { display: flex; flex-direction: column; gap: 4px; }
.so-filter label { font-size: 11px; text-transform: uppercase; letter-spacing: .05em; color: #6b7280; font-weight: 700; }
.so-filter input { border: 1px solid #d7dbe0; border-radius: 8px; padding: 7px 10px; font-size: 13px; width: 170px; }
.so-filter input:focus { outline: none; border-color: #2490ef; box-shadow: 0 0 0 3px rgba(36,144,239,.15); }
.so-filter .btn { border-radius: 8px; padding: 8px 18px; font-weight: 600; }
.so-count { color: #6b7280; font-size: 13px; margin: 2px 2px 12px; }
.so-tablecard { padding: 0; overflow: hidden; }
table.so-table { width: 100%; border-collapse: separate; border-spacing: 0; margin: 0; }
table.so-table thead th { background: #f8f9fb; font-size: 11px; text-transform: uppercase; letter-spacing: .04em; color: #6b7280; font-weight: 700; padding: 12px 14px; border-bottom: 1px solid #ebeef0; text-align: left; white-space: nowrap; }
table.so-table tbody td { padding: 11px 14px; border-bottom: 1px solid #f1f3f5; font-size: 13px; color: #1f272e; vertical-align: middle; }
table.so-table tbody tr.so-orow { cursor: pointer; }
table.so-table tbody tr.so-orow:hover { background: #f8fafc; }
table.so-table tbody tr.so-open { background: #eef6ff; }
.so-caret { display: inline-block; width: 14px; color: #9aa4af; transition: transform .15s; }
tr.so-open .so-caret { transform: rotate(90deg); color: #2490ef; }
.so-ordernr { font-weight: 600; color: #2490ef; }
.badge-status { display: inline-block; padding: 3px 10px; border-radius: 999px; font-size: 11px; font-weight: 600; text-transform: capitalize; }
.badge-confirmed { background: #e6f4ea; color: #137333; }
.badge-approved { background: #e7f1ff; color: #0b5ed7; }
.badge-default { background: #eef0f2; color: #495057; }
.so-detail-cell { background: #fbfcfd; padding: 12px 16px !important; }
table.so-lines { width: 100%; border-collapse: collapse; margin: 0; background: #fff; border: 1px solid #eef1f4; border-radius: 8px; }
table.so-lines th { font-size: 10px; text-transform: uppercase; letter-spacing: .04em; color: #8a94a0; font-weight: 700; padding: 7px 10px; border-bottom: 1px solid #e9edf1; text-align: left; }
table.so-lines td { padding: 7px 10px; border-bottom: 1px solid #f2f4f6; font-size: 12px; color: #333; }
table.so-lines tr:last-child td { border-bottom: none; }
.so-muted { color: #9aa4af; }
